def calc(expr: str) -> int | str:
    tokens = tokenize(expr)
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        return parse_additive()

    def parse_additive():
        left = parse_multiplicative()
        if left is None:
            return None
        while peek() in ('+', '-'):
            op = consume()
            right = parse_multiplicative()
            if right is None:
                return None
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_multiplicative():
        left = parse_unary()
        if left is None:
            return None
        while peek() in ('*', '/', '%'):
            op = consume()
            right = parse_unary()
            if right is None:
                return None
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    return None
                # truncate toward zero
                left = int(left / right) if (left % right != 0 and (left < 0) != (right < 0)) else left // right
            else:  # %
                if right == 0:
                    return None
                # a % b = a - b * trunc(a/b)
                q = int(left / right) if (left % right != 0 and (left < 0) != (right < 0)) else left // right
                left = left - right * q
        return left

    def trunc_div(a, b):
        if b == 0:
            return None
        # truncate toward zero
        result = a // b
        # Python floor division; adjust if signs differ and there's a remainder
        if (a < 0) != (b < 0) and a % b != 0:
            result += 1
        return result

    def parse_multiplicative():
        left = parse_unary()
        if left is None:
            return None
        while peek() in ('*', '/', '%'):
            op = consume()
            right = parse_unary()
            if right is None:
                return None
            if op == '*':
                left = left * right
            elif op == '/':
                q = trunc_div(left, right)
                if q is None:
                    return None
                left = q
            else:  # %
                q = trunc_div(left, right)
                if q is None:
                    return None
                left = left - right * q
        return left

    def parse_unary():
        if peek() == '-':
            consume()
            operand = parse_unary()
            if operand is None:
                return None
            return -operand
        return parse_power()

    def parse_power():
        base = parse_primary()
        if base is None:
            return None
        if peek() == '^':
            consume()
            # right operand of ^ may start with unary minus
            exp = parse_unary_for_power()
            if exp is None:
                return None
            if exp < 0:
                return None  # negative exponent is error
            if base == 0 and exp == 0:
                return 1
            return base ** exp
        return base

    def parse_unary_for_power():
        # unary minus allowed as right operand of ^
        if peek() == '-':
            consume()
            operand = parse_unary_for_power()
            if operand is None:
                return None
            return -operand
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            return None
        if tok == '(':
            consume()
            val = parse_expr()
            if val is None:
                return None
            if peek() != ')':
                return None
            consume()
            return val
        if isinstance(tok, int):
            consume()
            return tok
        return None

    result = parse_expr()
    if result is None or pos[0] != len(tokens):
        return "error"
    return result


def tokenize(expr: str):
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif expr[i] in '+-*/%^()':
            tokens.append(expr[i])
            i += 1
        else:
            tokens.append(expr[i])
            i += 1
    return tokens
